import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"04 · 分镜","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/honey-butter/04-storyboard.md","filePath":"lab/shuangyu-fries/honey-butter/04-storyboard.md","lastUpdated":1787456457000}'),o={name:"lab/shuangyu-fries/honey-butter/04-storyboard.md"};function h(l,t,i,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="_04-·-分镜" tabindex="-1">04 · 分镜 <a class="header-anchor" href="#_04-·-分镜" aria-label="Permalink to &quot;04 · 分镜&quot;">​</a></h1><blockquote><p>正式 AI 视频执行稿 ｜ 12 秒 / 9:16 ｜ 关键帧与 Demo 方向通过后使用</p></blockquote><h2 id="执行前提" tabindex="-1">执行前提 <a class="header-anchor" href="#执行前提" aria-label="Permalink to &quot;执行前提&quot;">​</a></h2><p>正式分镜不再重新讨论创意方向。进入本页前必须满足：</p><ol><li><a href="./01-creative">01 · 创意</a> 已通过；</li><li><a href="./02-keyframes">02 · 关键帧</a> 的 P0 和本镜首尾帧已通过；</li><li><a href="./03-demo-preview">03 · Demo 预览</a> 已确认节奏，并记录需要修正的动作；</li><li>Demo 中的假包装、临时文字、平台水印和随机音频均未被当作正式资产。</li></ol><h2 id="_12-秒时间线" tabindex="-1">12 秒时间线 <a class="header-anchor" href="#_12-秒时间线" aria-label="Permalink to &quot;12 秒时间线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>镜头</th><th>画面与动作</th><th>生成 / 后期</th><th>屏幕文字</th></tr></thead><tbody><tr><td>00:00.0–00:00.9</td><td>01 · 出题</td><td>杯装产品局部占下半部，三根薯条脆竖向露出</td><td>KF01 数字推近；包装与问题后期合成</td><td><strong>戴耳机。哪一声是蜂蜜黄油味？</strong></td></tr><tr><td>00:00.9–00:01.9</td><td>02 · A 声纹</td><td>单根产品从中央折断</td><td>KF02A / B 图生视频</td><td><strong>A</strong></td></tr><tr><td>00:01.9–00:03.0</td><td>03 · B 声纹</td><td>两根产品先后折断</td><td>KF03A / B 图生视频</td><td><strong>B</strong></td></tr><tr><td>00:03.0–00:04.2</td><td>04 · C 声纹</td><td>人物下半脸局部咬下一小段</td><td>KF04A / B 图生视频</td><td><strong>C</strong></td></tr><tr><td>00:04.2–00:05.4</td><td>05 · 作答</td><td>中央产品静止，三条波形纵向并列</td><td>KF05 + 后期真实波形</td><td><strong>你选哪一声？</strong></td></tr><tr><td>00:05.4–00:08.1</td><td>06 · remix</td><td>A、B、C、断面四个动作按四拍重组</td><td>复用镜头 02–04、08，不新生成复合动作</td><td>无</td></tr><tr><td>00:08.1–00:09.0</td><td>07 · 答案</td><td>三条波形合一，画面停住</td><td>复用 KF05，后期动效</td><td><strong>答案：都是。</strong></td></tr><tr><td>00:09.0–00:10.3</td><td>08 · 证据</td><td>断面轻转，焦点从外表面移到断口</td><td>KF08 图生视频</td><td><strong>味道听不见，脆可以。</strong></td></tr><tr><td>00:10.3–00:12.0</td><td>09 · 落版</td><td>终稿包装、三根产品和少量碎屑稳定落版</td><td>KF09 + 包装后期合成</td><td><strong>双宇食品 · 薯条脆</strong> / <strong>蜂蜜黄油味</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">前 4.2 秒不加模型音乐</p><p>视频模型如自动生成声音，一律只作动作同步参考，不进入正式混音。A / B / C 的最终声音在 <a href="./05-sound-edit">05 · 声音与剪辑</a> 独立完成。</p></div><h2 id="统一生成标准" tabindex="-1">统一生成标准 <a class="header-anchor" href="#统一生成标准" aria-label="Permalink to &quot;统一生成标准&quot;">​</a></h2><ul><li>每个动态镜头只使用本镜通过审核的首尾帧，不把 P0 直接当成所有镜头首帧。</li><li>统一 <code>9:16</code>，同一分辨率、奶油白 / 自然浅金 / 少量黑色的色彩体系。</li><li>P0 只锁定外观身份；M0 只锁定断面。不得继承参考图的背景、机位和手部。</li><li>一镜一个主动作；主体运动时相机锁定，焦点转移时主体不再增加动作。</li><li>包装、中文、logo、A / B / C、波形和字幕全部后期添加。</li><li>所有 Prompt 末尾排除文字、水印、UI、产品变形、油膜、蜂蜜液体和黄油块。</li></ul><h2 id="镜头-01-·-出题" tabindex="-1">镜头 01 · 出题 <a class="header-anchor" href="#镜头-01-·-出题" aria-label="Permalink to &quot;镜头 01 · 出题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF01 + 客户确认的包装工程文件</td></tr><tr><td>方式</td><td>静帧后期，不做视频生成</td></tr><tr><td>运动</td><td>全画面数字推近 2%，包装和产品之间无相对漂移</td></tr><tr><td>重点</td><td>第一帧同时看见口味身份和完整问题</td></tr><tr><td>废片</td><td>模型包装、伪文字、杯体变形、开场动画过多导致 0.9 秒读不完</td></tr></tbody></table><p>包装只在后期合成到 KF01 的预留位置。问题第一帧完整出现，不做逐字动画。</p><h2 id="镜头-02-·-a-声纹-单根折断" tabindex="-1">镜头 02 · A 声纹 / 单根折断 <a class="header-anchor" href="#镜头-02-·-a-声纹-单根折断" aria-label="Permalink to &quot;镜头 02 · A 声纹 / 单根折断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF02A + KF02B + P0 + M0</td></tr><tr><td>方式</td><td>首尾帧图生视频</td></tr><tr><td>动作窗口</td><td>1.0 秒；0.15 秒静止后只断一次</td></tr><tr><td>相机</td><td>锁定微距，不推拉、不环绕、不变焦</td></tr><tr><td>重点</td><td>单根、中央断裂、短而清楚；长度与粗细守恒</td></tr><tr><td>废片</td><td>弯曲、反复折断、断口愈合、碎屑爆炸、额外产品或手指</td></tr></tbody></table><p>正式生成沿用 <a href="./03-demo-preview#dv02-单根折断">Demo DV02</a> 的结构化 Prompt，并只加入 Demo 审核记录中的单项修正。一次只改动作、物理或镜头中的一层。</p><h2 id="镜头-03-·-b-声纹-双根折断" tabindex="-1">镜头 03 · B 声纹 / 双根折断 <a class="header-anchor" href="#镜头-03-·-b-声纹-双根折断" aria-label="Permalink to &quot;镜头 03 · B 声纹 / 双根折断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF03A + KF03B + P0 + M0</td></tr><tr><td>方式</td><td>首尾帧图生视频</td></tr><tr><td>动作窗口</td><td>1.1 秒；上方先断，下方延迟 20–60ms</td></tr><tr><td>相机</td><td>与镜头 02 相同的固定机位和白平衡</td></tr><tr><td>重点</td><td>两根始终分离，形成比 A 更厚的视觉层次</td></tr><tr><td>废片</td><td>两根融合、完全镜像同步、第三根出现、断口和碎屑完全复制</td></tr></tbody></table><p>正式生成沿用 <a href="./03-demo-preview#dv03-双根折断">Demo DV03</a>，保留自然微时差，不用复制镜头 02 再叠一层。</p><h2 id="镜头-04-·-c-声纹-咬下" tabindex="-1">镜头 04 · C 声纹 / 咬下 <a class="header-anchor" href="#镜头-04-·-c-声纹-咬下" aria-label="Permalink to &quot;镜头 04 · C 声纹 / 咬下&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF04A + KF04B + P0 + M0</td></tr><tr><td>方式</td><td>首尾帧图生视频</td></tr><tr><td>动作窗口</td><td>1.2 秒；唇前停 0.2 秒后完成一次咬下</td></tr><tr><td>相机</td><td>固定侧面近景，只保留下半脸</td></tr><tr><td>重点</td><td>同一人物、同一产品、自然闭合，不展示口腔细节</td></tr><tr><td>废片</td><td>完整人脸、嘴部变形、额外牙齿、产品穿模、夸张咀嚼</td></tr></tbody></table><p>正式生成沿用 <a href="./03-demo-preview#dv04-咬下">Demo DV04</a>。若连续三轮人体稳定性仍不通过，按关键帧页的失败回退改为产品碰撞声纹，不继续消耗次数硬修嘴部。</p><h2 id="镜头-05-·-作答界面" tabindex="-1">镜头 05 · 作答界面 <a class="header-anchor" href="#镜头-05-·-作答界面" aria-label="Permalink to &quot;镜头 05 · 作答界面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF05 + A / B / C 最终声音</td></tr><tr><td>方式</td><td>后期动效，不做视频生成</td></tr><tr><td>运动</td><td>三条波形以相同缩放从左向右播放一次，中央产品不动</td></tr><tr><td>重点</td><td>选项权重一致，停顿至少 1 秒</td></tr><tr><td>废片</td><td>装饰性假波形、某个选项被提前高亮、波形比例不一致</td></tr></tbody></table><h2 id="镜头-06-·-声纹-remix" tabindex="-1">镜头 06 · 声纹 remix <a class="header-anchor" href="#镜头-06-·-声纹-remix" aria-label="Permalink to &quot;镜头 06 · 声纹 remix&quot;">​</a></h2><p>不让视频模型一次生成四个动作。后期按以下节拍重组正式镜头：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 拍：镜头 02，取断裂前后各 4–6 帧</span></span>
<span class="line"><span>第 2 拍：镜头 03，取两根刚刚错开的一刻</span></span>
<span class="line"><span>第 3 拍：镜头 04，取咬下动作完成的一刻</span></span>
<span class="line"><span>第 4 拍：镜头 08，焦点抵达断面的时刻</span></span></code></pre></div><p>四拍之间只用硬切或动作匹配，不加发光圆环、闪白、速度模糊和魔法粒子转场。</p><h2 id="镜头-07-·-答案" tabindex="-1">镜头 07 · 答案 <a class="header-anchor" href="#镜头-07-·-答案" aria-label="Permalink to &quot;镜头 07 · 答案&quot;">​</a></h2><p>复用 KF05。三条真实波形在 4–6 帧内收束成一条，静音 0.1 秒后出现「答案：都是。」；不做综艺爆炸字效，不解释规则。</p><h2 id="镜头-08-·-断面证据" tabindex="-1">镜头 08 · 断面证据 <a class="header-anchor" href="#镜头-08-·-断面证据" aria-label="Permalink to &quot;镜头 08 · 断面证据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF08 + P0 + M0</td></tr><tr><td>方式</td><td>单帧图生视频</td></tr><tr><td>动作窗口</td><td>1.3 秒；产品轻转小于 12°，焦点只移动一次</td></tr><tr><td>相机</td><td>100mm 微距机位锁定</td></tr><tr><td>重点</td><td>先见干爽表面，再清楚看见有依据的真实断面</td></tr><tr><td>废片</td><td>相机环绕、主体大角度旋转、孔洞放大、面包纤维、油光或液体</td></tr></tbody></table><p>正式生成沿用 <a href="./03-demo-preview#dv08-断面轻转">Demo DV08</a>，最终至少有 0.5 秒断面清晰停留。</p><h2 id="镜头-09-·-产品落版" tabindex="-1">镜头 09 · 产品落版 <a class="header-anchor" href="#镜头-09-·-产品落版" aria-label="Permalink to &quot;镜头 09 · 产品落版&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>执行</th></tr></thead><tbody><tr><td>输入</td><td>KF09 + 客户确认包装工程文件</td></tr><tr><td>方式</td><td>静帧后期合成；可做不超过 2% 的数字推近</td></tr><tr><td>重点</td><td>包装正面准确、三根 P0 产品构图稳定、文字清楚保留 1.2 秒以上</td></tr><tr><td>废片</td><td>模型重绘包装、logo 或中文漂移、碎屑遮字、最后仍有动态变形</td></tr></tbody></table><p>最后一声咔嚓发生在 11.6 秒，视觉层保持稳定，用声音尾部接回第一帧。</p><h2 id="正式生成顺序" tabindex="-1">正式生成顺序 <a class="header-anchor" href="#正式生成顺序" aria-label="Permalink to &quot;正式生成顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>任务</th><th>通过后进入</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>镜头 02 单根折断</td><td>镜头 03 双根折断</td></tr><tr><td style="text-align:right;">2</td><td>镜头 03 双根折断</td><td>镜头 04 咬下</td></tr><tr><td style="text-align:right;">3</td><td>镜头 04 咬下</td><td>镜头 08 断面</td></tr><tr><td style="text-align:right;">4</td><td>镜头 08 断面</td><td>01 / 05 / 07 / 09 后期版式</td></tr><tr><td style="text-align:right;">5</td><td>九镜无声粗剪</td><td>声音与剪辑</td></tr></tbody></table><h2 id="本步审核" tabindex="-1">本步审核 <a class="header-anchor" href="#本步审核" aria-label="Permalink to &quot;本步审核&quot;">​</a></h2><ul><li>[ ] 每个动态镜头都使用本镜关键帧，不从文本直接盲生成</li><li>[ ] Demo 反馈已经逐项写入对应镜头，未整体重写已通过部分</li><li>[ ] 02、03、04、08 各自只有一个主动作</li><li>[ ] P0 产品形态和 M0 断面在所有镜头中保持一致</li><li>[ ] 包装、中文、logo、波形和字幕全部由后期完成</li><li>[ ] 九镜无声粗剪精确为 12.0 秒，节奏通过后才进入声音制作</li></ul><hr><p><strong>上一步</strong> ← <a href="./03-demo-preview">03 · Demo 预览</a> ｜ <strong>下一步</strong> → <a href="./05-sound-edit">05 · 声音与剪辑</a></p>`,42)])])}const u=d(o,[["render",h]]);export{c as __pageData,u as default};
